import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","description":"!Chainy logo","frontmatter":{"title":"Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","description":"!Chainy logo","source":"README.md","category":"Start here","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/readme.md","filePath":"content/readme.md"}'),r={name:"content/readme.md"};function i(s,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai">Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)<a class="header-anchor" href="#chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai" aria-label="Link to this section">​</a></h1><p><img src="/Chainy-Docs/attachments/docs/media/brand/chainy-logo.png" alt="Chainy logo"></p><p>Chainy is an offline Android learning game for ages 12–17. Players restore island services through fictional wallet/purchase actions and evidence-based Blockchain repair. Contextual Quiz supports the journey; standalone Wordle and BlockMatch are deferred from the first beta. Unity runs the game; SQLite keeps profiles and progress on the device.</p><p><strong>Cryptita Plays community beta testing: November 10, 2026. Pre-final defense: November 21, 2026.</strong></p><p>This repository holds the team&#39;s decisions, documentation and task plan. The October 23 revision adopts <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a>, preserving usable technical infrastructure and separating core, stretch, full and later-service work. <a href="/Chainy-Docs/content/docs/gdd-template-editions.html">All GDD editions and update notes</a> are indexed; superseded documents remain recoverable.</p><h2 id="open-your-work">Open your work<a class="header-anchor" href="#open-your-work" aria-label="Link to this section">​</a></h2><table><thead><tr><th>I need to…</th><th>Open</th></tr></thead><tbody><tr><td>Understand the project</td><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Current decisions</a></td></tr><tr><td>Find my responsibilities and tasks</td><td><a href="/Chainy-Docs/content/docs/team-delegation.html">Team roles</a></td></tr><tr><td>Move task cards and edit the timeline</td><td><a href="https://owenlim225.github.io/Chainy-Docs/board/">Live team board</a> · <a href="/Chainy-Docs/content/docs/team-board-guide.html">Quick guide</a></td></tr><tr><td>Understand how the game plays</td><td><a href="/Chainy-Docs/content/docs/game-design.html">Game design</a></td></tr><tr><td>Build or review the systems</td><td><a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a></td></tr><tr><td>Find research, testing or supporting documents</td><td><a href="/Chainy-Docs/content/docs/documentation-index.html">Documentation index</a></td></tr></tbody></table><p>Use your individual account on the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a> to edit cards and dates. Changes are recorded by name and copied to the existing GitHub issues. Trello is disconnected; teammates do not need GitHub accounts.</p><p>Christian&#39;s supplied report lists several components in progress and the player controller completed. Those are <strong>tech-lead-reported component states</strong>, not independently tested whole-task completion. The old zero-progress statement is superseded.</p><p>Game source is linked at <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>; the supplied design also identifies a private Unity Cloud project. Christian must confirm which source location the team builds from. Earlier specifications and the previous illustrated PDF are <a href="/Chainy-Docs/content/docs/archive/readme.html">historical references</a>.</p></div>',1)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
